"""Directed and ordinary versions of the ratio theorems on printed page 220."""
from math import hypot
from construction_followup import constructed
from midpoint_lessons import views, edges, mid, foot, drawing


def ratios():
    def diagram(a,b,c,x,y,z):
        points=dict(A=a,B=b,C=c,X=x,Y=y,Z=z)
        points.update(H=foot(a,x,y),K=foot(b,x,y),L=foot(c,x,y))
        return points
    a,b,c=(0,0),(6,0),(2,6);x=(3,0);y=(5,1.5);z=(-1,-3)
    p=diagram(a,b,c,x,y,z);base=edges('ABC')+[('Z','Y'),('Z','A')]
    m890=constructed(890,'Прямая без вершин ABC пересекает AB в X, BC в Y и продолжение AC в Z. Докажи равенство (AX/XB)·(BY/YC)·(CZ/ZA)=1 для обычных длин.',
        'Каждое отношение отрезков равно отношению расстояний двух вершин до секущей. Три таких отношения перемножаются в 1.',
        'Опусти из A, B и C перпендикуляры к секущей. Обозначь их длины a,b,c.',
        [('Почему AX/XB=a/b?', 'Пусть H,K,L — основания перпендикуляров из A,B,C к секущей. Сравни прямоугольные треугольники AXH и BXK. Острые углы, образованные прямыми AB и XY, равны. Поэтому их гипотенузы AX и XB относятся как высоты a=AH и b=BK.',
          'Если секущая встречает AB под прямым углом, тогда X=H=K и отношение сразу равно AH/BK.'),
         ('Какие отношения получаются на других двух прямых?', 'Той же проекцией в точке Y получаем BY/YC=b/c. В точке Z обе вершины могут лежать по одну сторону секущей, но острый угол между прямыми одинаков, поэтому CZ/ZA=c/a.',
          'Для любого T на секущей расстояние P до неё равно PT·sin φ, где φ — меньший угол между PT и секущей.'),
         ('Как сокращается произведение?', '(a/b)·(b/c)·(c/a)=1. Ни одно расстояние не равно нулю, поскольку секущая не проходит через вершину.',
          'Это теорема Менелая для двух внутренних пересечений и одного внешнего.')],
        views(p,base,((),()),([('A','H'),('B','K')],('AXH','BXK')),([('A','H'),('B','K'),('C','L')],()),((),('ABC',))),
        (3,'Если AX/XB=2 и BY/YC=3, чему равно ZA/CZ?', ['6'],'Произведение первых двух отношений равно отношению, обратному CZ/ZA.'))
    a,b,c=(0,0),(6,0),(2,6);x=(-2,0);y=(10/7,48/7);z=(4,12)
    p=diagram(a,b,c,x,y,z);base=edges('ABC')+[('X','A'),('C','Y'),('A','Z'),('Y','Z')]
    m891=constructed(891,'Секущая пересекает продолжения всех трёх сторон ABC. Обозначь пересечения с AB, BC и CA через X,Y,Z. Докажи ту же формулу Менелая для положительных длин.',
        'Расположение оснований на продолжениях сохраняет отношения абсолютных значений. Получается (AX/XB)·(BY/YC)·(CZ/ZA)=1.',
        'Снова измерь расстояния от трёх вершин до секущей, теперь не предполагая пересечения самих сторон.',
        [('Пропадает ли сравнение у внешней точки X?', 'Пусть расстояния A, B, C до секущей равны a,b,c. Прямые AX и BX совпадают. Угол между этой прямой и секущей даёт один и тот же положительный синус для обоих отрезков. Поэтому a=AX·sin φ и b=BX·sin φ, значит AX/XB=a/b.',
          'Синусы смежных углов равны, а длины отрезков положительны.'),
         ('Как учесть два оставшихся продолжения?', 'На прямой BC общий синус даёт BY/YC=b/c. На прямой CA получаем CZ/ZA=c/a. Никакой из этих расчётов не использует внутреннее положение точки между вершинами.',
          'Поскольку треугольник и пересечения конечны и невырождены, синус угла пересечения ненулевой.'),
         ('Как проверить итог на чертеже?', 'Перемножь отношения: a, b и c сокращаются попарно. Все три расстояния по-прежнему измеряются по перпендикуляру к одной и той же секущей.',
          'Для всех трёх точек на продолжениях произведение обычных отношений тоже равно единице.')],
        views(p,base,((),()),([('A','H'),('B','K')],()),([('B','K'),('C','L')],()),([('A','H'),('B','K'),('C','L')],())),
        (1,'Если расстояния A и B до секущей равны 2 и 8, напиши AX/XB десятичной дробью.', ['0,25','0.25'],'Раздели 2 на 8.'))
    a,b,c=(0,0),(6,0),(2,6)
    p0=dict(A=a,B=b,C=c,X=mid(a,b),Y=mid(b,c),Z=mid(c,a));p=diagram(a,b,c,(3,0),(5,1.5),(-1,-3))
    base=edges('ABC')
    m892=constructed(892,'Обратная теорема Менелая: по отношениям в точках X на AB, Y на BC и Z на CA надо доказать их коллинеарность. Разбери, какое условие о расположении точек требуется при использовании обычных длин.',
        'Для обычных длин нужны единичное произведение и нечётное число внешних точек. В направленных отношениях оба условия объединяются в (AX/XB)·(BY/YC)·(CZ/ZA)=−1.',
        'Сначала проверь середины трёх сторон. Может ли без условия о расположении единичного произведения быть достаточно?',
        [('Что показывает проверка без знаков?', 'Возьми X,Y,Z серединами сторон. Три положительных отношения равны 1, но середины образуют треугольник. Для секущей должны быть внешними одна или три точки. Удобно считать каждое отношение положительным для внутреннего деления и отрицательным для внешнего.',
          'Эта оговорка важна при чтении записи через длины на стр. 220 издания 2023 года.'),
         ('Что известно о знаках расстояний до XY?', 'Проведи XY. Пусть a,b,c — направленные расстояния от A,B,C до XY: выбери один знак в одной полуплоскости, другой в противоположной. При внутреннем делении X вершины A и B по разные стороны прямой, а при внешнем — по одну. Для направленного x=AX/XB имеем a/b=−x. Аналогично b/c=−y при y=BY/YC.',
          'Абсолютные значения равны по прямоугольным треугольникам из задачи 890. Вершины и пересечения считаются различными.'),
         ('Почему Z должна лежать именно на XY?', 'Из двух равенств a/c=xy. Условие xyz=−1 даёт c/a=−z, где z=CZ/ZA. В точке Z направленные расстояния линейно интерполируются: её расстояние равно (c+za)/(1+z), то есть нулю. Значит Z принадлежит XY.',
          'Для точки Z=(C+zA)/(1+z) любая координата или направленное расстояние до фиксированной прямой вычисляется той же взвешенной суммой. Конечная точка не даёт z=−1.')],
        [drawing(p0,base+edges('XYZ')),drawing(p0,base+edges('XYZ'),('XYZ',)),drawing(p,base+[('X','Y'),('A','H'),('B','K')]),drawing(p,base+[('Z','Y'),('A','Z')])],
        (1,'Если в конфигурации Менелая две из трёх точек внутренние, сколько точек внешние?', ['1'],'Для прямой, пересекающей внутренность треугольника, третья точка должна лежать за его стороной.'))
    a,b,c=(0,0),(8,0),(2,6);x=(2,0);y=(4,4);z=(.8,2.4);o=(2,2)
    p=dict(A=a,B=b,C=c,X=x,Y=y,Z=z,O=o);base=edges('ABC')+[('C','X'),('A','Y'),('B','Z')]
    m893=constructed(893,'X лежит на прямой AB, Y на BC, Z на CA. Прямые CX, AY и BZ пересекаются в одной точке O. Докажи произведение Чевы (AX/XB)·(BY/YC)·(CZ/ZA)=1 для обычных длин.',
        'Каждое отношение выражается через две из трёх площадей OAB, OBC, OCA. В произведении все три площади сокращаются.',
        'Возьми треугольники OCA и OCB. Их высоты к одной прямой CO относятся как отрезки AX и XB.',
        [('Как выразить AX/XB через площади возле O?', 'Так как C,O,X лежат на одной прямой, у треугольников OCA и OCB общее основание OC. Расстояния A и B до OC равны AX·sin φ и BX·sin φ при одном угле между AB и OC. Значит AX/XB=S(OCA)/S(OCB).',
          'Длина высоты вычисляется тем же способом, когда X на продолжении AB.'),
         ('Что дают две другие прямые через O?', 'Сравни OAB и OAC по основанию OA: BY/YC=S(OAB)/S(OAC). Сравнение OBC и OBA по основанию OB даёт CZ/ZA=S(OBC)/S(OBA).',
          'Треугольники задают те же площади при любой записи их вершин в другом порядке.'),
         ('Почему три дроби перемножаются в 1?', 'Подставь найденные дроби. Площадь OCA сокращается с OAC, OCB с OBC, OAB с OBA. Доказательство использует обычные площади и остаётся верным для внешней точки O, если пересечения отличны от вершин.',
          'Необходимое условие для трёх пересекающихся чевиан называют теоремой Чевы.')],
        views(p,base,((),()),((),('OCA','OCB')),((),('OAB','OAC','OBC')),((),('ABC',))),
        (3,'Если AX/XB=2 и BY/YC=1/3, запиши CZ/ZA десятичной дробью.', ['1,5','1.5'],'Найди число, которое при умножении на 2/3 даст 1.'))
    m894=constructed(894,'Даны X на AB, Y на BC и Z на CA или на продолжениях. При каком условии на отношения можно применить обратную теорему Чевы и заключить, что CX, AY и BZ проходят через одну точку?',
        'Для трёх внутренних точек достаточно произведения 1. При внешних делениях произведение берут со знаками, и для общей конечной точки нужно исключить параллельные чевианы.',
        'Сначала проведи две чевианы для внутренних точек. Их пересечение помогает определить след третьей чевианы на CA.',
        [('Как доказать обратную теорему при внутренних точках?', 'Пусть x=AX/XB, y=BY/YC, z=CZ/ZA. При внутренних X,Y прямые CX и AY пересекаются внутри ABC в O. Прямая BO встречает CA в Z′. По уже доказанной теореме CZ′/Z′A=1/(xy)=z. Внутренняя точка с таким отношением единственна, значит Z′=Z.',
          'Две чевианы к внутренним точкам пересекаются в треугольнике.'),
         ('Зачем различать внутреннее и внешнее деление?', 'Каждое внешнее отношение запиши со знаком минус. Для Чевы требуется xyz=+1, то есть положительное произведение длин и чётное число внешних точек. Без знаков та же запись возможна у точек секущей из задачи 890, чьи чевианы вовсе не обязаны пересекаться.',
          'В записи с обычными длинами на стр. 220 издания 2023 года требуется учитывать расположение точек.'),
         ('Когда общая точка конечна?', 'В координатах A=(0,0), B=(1,0), C=(0,1) положи s=1+x+xy. При s≠0 точка O=(x/s,xy/s) лежит на CX и AY; подстановка z=1/(xy) показывает, что O лежит и на BZ. При s=0 направления CX, AY и BZ совпадают, и три прямые параллельны. Для внутренних точек s>0 автоматически.',
          'Эти координаты можно ввести вдоль AB и AC даже при непрямом угле. Доли A,B,C равны 1/s,x/s,xy/s; отношение двух соответствующих долей задаёт каждое деление.')],
        views(p,base,((),()),((),('OCA','OCB')),((),('ABC',)),((),('OAB','OBC','OCA'))),
        (1,'Если внутренние отношения AX/XB=3 и BY/YC=2, чему равно ZA/CZ для пересекающихся чевиан?', ['6'],'Из xyz=1 получаем 1/z=xy.'))
    for obj in [m890,m891,m892,m893,m894]:
        for i,v in enumerate(obj['model']['views'].values()):
            visible={k for row in v['segments']+v.get('polygons',[]) for k in row}
            visible.update(f'{k}__v{i}' for k in 'XYZ')
            v['points']=[k for k in v['points'] if k in visible]
    return [m890,m891,m892,m893,m894]
